n = int(input())
s = input()

balance = 0
ans = 0

for i in range(n):
    if s[i] == '+':
        balance += 1
    else:
        balance -= 1
    # 如果累加值小于0，后续前缀均不合法，直接退出
    if balance < 0:
        break
    # 累加值等于0时，找到一个合法前缀，记录其长度
    elif balance == 0:
        ans = i + 1

print(ans)
